mapper.insert:
INSERT INTO pipeline_execution (pipeline_id, status, executed_by, heartbeat_at, triggered_by, trigger_id, created_at)
VALUES (#{pipelineId}, 'PENDING', #{executedBy}, #{heartbeatAt}, #{triggeredBy}, #{triggerId,jdbcType=BIGINT},
        )

mapper.update:
UPDATE pipeline_execution
   SET status = #{status}
       , started_at = #{startedAt}
       , heartbeat_at = #{startedAt}
       , completed_at = #{completedAt}
       , error_message = #{errorMessage}
 WHERE id = #{executionId}
   AND status IN

UPDATE pipeline_execution
   SET status = #{status}, completed_at = #{completedAt}
 WHERE id = #{executionId}
   AND status IN 
   AND cancel_requested_at IS NULL

mapper.select:
SELECT id, pipeline_id
  FROM pipeline_execution
 WHERE tenant_id = #{tenantId}
   AND status IN 
   AND COALESCE(heartbeat_at, started_at, created_at) < #{threshold}

mapper.update:
UPDATE pipeline_execution
   SET status = 'FAILED', completed_at = #{now}, error_message = #{message,jdbcType=VARCHAR}
 WHERE id = #{executionId}
   AND status IN

UPDATE pipeline_step_execution
   SET status = 'FAILED', error_message = #{message,jdbcType=VARCHAR}, completed_at = #{now}
 WHERE execution_id = #{executionId}
   AND status = 'RUNNING'

UPDATE pipeline_step_execution
   SET status = 'SKIPPED', error_message = #{message,jdbcType=VARCHAR}, completed_at = #{now}
 WHERE execution_id = #{executionId}
   AND status = 'PENDING'

UPDATE pipeline_execution
   SET status = 'CANCELLED', completed_at = #{now}, error_message = #{message},
       cancel_requested_at = #{now}, cancel_requested_by = #{userId}
 WHERE id = #{executionId}
   AND status = 'PENDING'

mapper.select:
SELECT 1 FROM pipeline_step_execution
 WHERE step_id = #{stepId}
   AND id <> #{stepExecId}
   AND (status = 'RUNNING' OR (status <> 'PENDING' AND completed_at >= #{startedAt}))

mapper.update:
UPDATE pipeline_step_execution
   SET output_rows = #{outputRows,jdbcType=INTEGER}, log = #{log,jdbcType=VARCHAR}
 WHERE id = #{stepExecId}

UPDATE pipeline_step_execution
   SET injected_last_run_at = #{value,jdbcType=TIMESTAMP}
 WHERE id = #{stepExecId}

UPDATE pipeline_step_execution
   SET status = #{status}
       , output_rows = #{outputRows}
       , log = #{log}
       , error_message = #{errorMessage}
       , started_at = #{startedAt}
       , completed_at = #{completedAt}
 WHERE id = #{stepExecId}
   AND EXISTS (SELECT 1 FROM pipeline_execution pe
                WHERE pe.id = pipeline_step_execution.execution_id
                  AND pe.status IN )

mapper.delete:
DELETE FROM pipeline_execution
 WHERE created_at < #{cutoff}
   AND status = 'COMPLETED'
